"""
A small amount of explicit domain knowledge about the official Crafting
Interpreters Lox benchmark scripts, used for two things:

1. Telling apart "correctness check" output -- deterministic program-behavior
   values that should come out byte-identical no matter which interpreter
   runs the script, or how fast it is (a computed tree depth, a checksum) --
   from actual performance metrics (elapsed time, throughput). Correctness
   values get *validated* against the official jlox reference rather than
   charted; charting something that never varies (short of a bug) is noise.

2. Flagging the couple of positions where a *bigger* number is the better
   (faster) result -- the opposite of every timing metric elsewhere.

This is different in kind from the old "primary metric" config that used to
live here: that picked one arbitrary number to represent a whole benchmark.
This is instead a real semantic distinction in what the scripts print,
checkable against jlox rather than asserted by fiat.
"""

# Any entry whose text label (case-insensitive) contains one of these
# substrings is a correctness-check value, not a performance metric.
CHECK_LABEL_SUBSTRINGS = ("check", "depth", "num trees")

# A couple of benchmarks print a correctness-check value with no preceding
# text label, so the label-based rule above won't catch it. These are
# 0-based positions within that benchmark's list of entries.
CHECK_POSITIONS_BY_BENCHMARK = {
    "zoo.lox": {0},  # total iteration checksum, printed before the elapsed time
}

# zoo_batch.lox runs for a fixed ~10s and reports how much work got done in
# that window -- for these positions a bigger number means a faster
# interpreter, unlike every timing metric elsewhere.
HIGHER_IS_BETTER_POSITIONS = {
    "zoo_batch.lox": {0, 1},  # total operations done, and batches completed
}


def is_check_entry(benchmark, index, label):
    if label and any(s in label.lower() for s in CHECK_LABEL_SUBSTRINGS):
        return True
    return index in CHECK_POSITIONS_BY_BENCHMARK.get(benchmark, set())


def is_higher_better(benchmark, index):
    return index in HIGHER_IS_BETTER_POSITIONS.get(benchmark, set())
